def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    priority = {"pass": 0, "skip": 1, "fail": 2}

    def update_result(name: str, status: str) -> None:
        if not name:
            return
        existing = results.get(name)
        if existing is None or priority[status] > priority.get(existing, 0):
            results[name] = status

    def make_test_name(classname: str, name: str) -> str:
        classname = (classname or "").strip()
        name = (name or "").strip()
        if classname and name:
            return f"{classname}.{name}"
        return name or classname

    def parse_xml_text(xml_text: str) -> bool:
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return False

        processed = set()

        for parent in root.iter():
            if not parent.tag.endswith("testsuite"):
                continue
            suite_name = parent.attrib.get("name", "").strip()
            for child in list(parent):
                if not child.tag.endswith("testcase"):
                    continue
                processed.add(id(child))
                classname = child.attrib.get("classname", "").strip()
                name = child.attrib.get("name", "").strip()
                if not classname and suite_name:
                    classname = suite_name
                test_name = make_test_name(classname, name)
                has_fail = False
                has_skip = False
                for elem in child.iter():
                    if elem is child:
                        continue
                    tag = elem.tag
                    if tag.endswith("failure") or tag.endswith("error"):
                        has_fail = True
                        break
                    if tag.endswith("skipped"):
                        has_skip = True
                status = "fail" if has_fail else "skip" if has_skip else "pass"
                update_result(test_name, status)

        for tc in root.iter():
            if not tc.tag.endswith("testcase") or id(tc) in processed:
                continue
            classname = tc.attrib.get("classname", "").strip()
            name = tc.attrib.get("name", "").strip()
            test_name = make_test_name(classname, name)
            has_fail = False
            has_skip = False
            for elem in tc.iter():
                if elem is tc:
                    continue
                tag = elem.tag
                if tag.endswith("failure") or tag.endswith("error"):
                    has_fail = True
                    break
                if tag.endswith("skipped"):
                    has_skip = True
            status = "fail" if has_fail else "skip" if has_skip else "pass"
            update_result(test_name, status)

        return True

    xml_blocks = []

    testsuites_match = re.search(r"<testsuites\b[\s\S]*?</testsuites>", log)
    if testsuites_match:
        xml_blocks.append(testsuites_match.group(0))

    for match in re.finditer(r"<testsuite\b[\s\S]*?</testsuite>", log):
        xml_blocks.append(match.group(0))

    for block in xml_blocks:
        parse_xml_text(block)

    def parse_attrs(text: str) -> dict[str, str]:
        attrs = {}
        for match in re.finditer(r'(\w+)\s*=\s*(".*?"|\'.*?\')', text, re.DOTALL):
            attrs[match.group(1)] = match.group(2)[1:-1]
        return attrs

    for match in re.finditer(r"<testcase\b([^>]*)>(.*?)</testcase>", log, re.DOTALL):
        attrs = parse_attrs(match.group(1))
        classname = attrs.get("classname", "")
        name = attrs.get("name", "")
        test_name = make_test_name(classname, name)
        if not test_name:
            continue
        body = match.group(2)
        if re.search(r"<(failure|error)\b", body):
            status = "fail"
        elif re.search(r"<skipped\b", body):
            status = "skip"
        else:
            status = "pass"
        update_result(test_name, status)

    for match in re.finditer(r"<testcase\b([^>]*)/>", log):
        attrs = parse_attrs(match.group(1))
        test_name = make_test_name(attrs.get("classname", ""), attrs.get("name", ""))
        if test_name:
            update_result(test_name, "pass")

    for line in log.splitlines():
        match = re.search(r"^(.+?::.+?)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", line)
        if match:
            status_map = {
                "PASSED": "pass",
                "FAILED": "fail",
                "ERROR": "fail",
                "SKIPPED": "skip",
            }
            update_result(match.group(1).strip(), status_map[match.group(2)])
            continue

        match = re.search(r"^(\S+)\s+\(([^)]+)\)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)", line)
        if match:
            status_map = {
                "ok": "pass",
                "FAIL": "fail",
                "ERROR": "fail",
                "skipped": "skip",
            }
            test_name = f"{match.group(2)}.{match.group(1)}"
            update_result(test_name, status_map[match.group(3)])
            continue

        match = re.search(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
        if match:
            status_map = {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}
            update_result(match.group(2), status_map[match.group(1)])
            continue

        match = re.search(r"^\s*(✓|✕|×|✖|✗|○)\s+(.*)", line)
        if match:
            symbol = match.group(1)
            name = match.group(2).strip()
            if not name:
                continue
            if symbol == "✓":
                status = "pass"
            elif symbol == "○":
                status = "skip"
            else:
                status = "fail"
            update_result(name, status)
            continue

    return results
